#!/usr/bin/env python3
"""Place source glyphs in ASCII positions while preserving source artwork."""
import argparse
from pathlib import Path


def remap(kind, data):
    if kind == "alto":
        if len(data) != 256 * 12 or any(data[128 * 12:]):
            raise ValueError("Expected 256 Alto slots with an empty upper half")
        return data[:128 * 12]
    if kind == "spectrum":
        if len(data) != 96 * 8:
            raise ValueError("Expected 96 Spectrum glyphs")
        output = bytearray(128 * 8)
        output[0x20 * 8:] = data
        # Spectrum block graphics are generated by firmware, not stored in ROM.
        for pattern in range(16):
            for y in range(8):
                bits = pattern >> (2 if y >= 4 else 0)
                output[pattern * 8 + y] = (0xF0 if bits & 1 else 0) | (0x0F if bits & 2 else 0)
        return bytes(output)

    if len(data) != 128 * 8:
        raise ValueError(f"Expected 128 {kind} glyphs")
    output = bytearray(128 * 8)
    if kind.startswith("pet-"):
        blocks = ((0x00, 0x60), (0x20, 0x20), (0x40, 0x00), (0x60, 0x40))
    elif kind == "atari":
        blocks = ((0x00, 0x40), (0x20, 0x00), (0x40, 0x20), (0x60, 0x60))
    else:
        raise ValueError(f"Unknown map: {kind}")
    for destination, source in blocks:
        output[destination * 8:(destination + 0x20) * 8] = data[source * 8:(source + 0x20) * 8]
    return bytes(output)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("kind", choices=("pet-graphics", "pet-business", "spectrum", "atari", "alto"))
    parser.add_argument("source", type=Path)
    parser.add_argument("output", type=Path)
    args = parser.parse_args()
    args.output.write_bytes(remap(args.kind, args.source.read_bytes()))
    print(f"Wrote {args.output}")


if __name__ == "__main__":
    main()
